import{_ as o,o as t,c as a,a2 as r}from"./chunks/framework.mRCPFc5l.js";const p=JSON.parse('{"title":"Troubleshooting","description":"","frontmatter":{"title":"Troubleshooting","order":25},"headers":[],"relativePath":"learn/mod/troubleshooting.md","filePath":"learn/mod/troubleshooting.md","lastUpdated":1786957039000}'),l={name:"learn/mod/troubleshooting.md"};function i(s,e,n,c,d,h){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h1><h2 id="load-failure" tabindex="-1">Load Failure <a class="header-anchor" href="#load-failure" aria-label="Permalink to &quot;Load Failure&quot;">​</a></h2><p><strong>Symptom</strong>: Your Mod doesn&#39;t appear in the UMM list, or shows as failed to load.</p><p><strong>Troubleshooting</strong>:</p><ol><li>Does <code>Info.json</code>&#39;s <code>AssemblyName</code> match the actual DLL filename</li><li>Is <code>EntryMethod</code> in the format <code>Namespace.Class.Load</code></li><li>Was the DLL actually copied to the <code>Mods/MyFirstMod/</code> directory</li><li>Does <code>Load</code> return <code>true</code></li><li>Check the UMM log for error messages</li></ol><h2 id="patches-not-taking-effect" tabindex="-1">Patches Not Taking Effect <a class="header-anchor" href="#patches-not-taking-effect" aria-label="Permalink to &quot;Patches Not Taking Effect&quot;">​</a></h2><p><strong>Symptom</strong>: You wrote a Harmony patch, but the game behavior hasn&#39;t changed.</p><p><strong>Troubleshooting</strong> (see <a href="./harmony-lifecycle">Patch Lifecycle</a>):</p><ol><li>The class must be <code>public static class</code> with <code>[HarmonyPatch]</code></li><li>Was <code>PatchAll</code> called in <code>OnToggle(true)</code></li><li>Do the target method/class/parameter types exactly match (watch for overloads)</li><li>Use <code>GetPatchInfo</code> to check if patches were actually applied</li><li>Was the target method already called before the Mod was enabled</li></ol><h2 id="nullreferenceexception" tabindex="-1">NullReferenceException <a class="header-anchor" href="#nullreferenceexception" aria-label="Permalink to &quot;NullReferenceException&quot;">​</a></h2><p><strong>Symptom</strong>: <code>NullReferenceException</code> in the log.</p><p><strong>Troubleshooting</strong>:</p><ol><li>Did you access <code>Settings</code> before <code>OnToggle</code></li><li>Could <code>__instance</code> be null (static method or null reference)</li><li>Decompile to confirm the actual field/property names of the target method</li></ol><h2 id="transpiler-crash-or-unexpected-behavior" tabindex="-1">Transpiler Crash or Unexpected Behavior <a class="header-anchor" href="#transpiler-crash-or-unexpected-behavior" aria-label="Permalink to &quot;Transpiler Crash or Unexpected Behavior&quot;">​</a></h2><p><strong>Symptom</strong>: After applying a Transpiler, the game crashes or behaves strangely.</p><p><strong>Troubleshooting</strong> (see <a href="./harmony-transpiler-practice">Transpiler Practice</a>):</p><ol><li>Use dnSpy to view the target method&#39;s real IL, confirming the matched instruction sequence exists</li><li>Degrade gracefully on match failure (<code>IsValid</code> check), don&#39;t throw directly</li><li>First add logging to output the instruction sequence and verify each one</li></ol><h2 id="settings-not-saved" tabindex="-1">Settings Not Saved <a class="header-anchor" href="#settings-not-saved" aria-label="Permalink to &quot;Settings Not Saved&quot;">​</a></h2><p><strong>Symptom</strong>: Settings revert to defaults after restarting the game.</p><p><strong>Troubleshooting</strong>:</p><ol><li>Is <code>OnSaveGUI</code> bound to <code>Settings.OnSaveGUI</code></li><li>Is <code>Settings.Save</code> being called</li><li>Are the property types supported by UMM</li></ol><h2 id="ci-build-failure" tabindex="-1">CI Build Failure <a class="header-anchor" href="#ci-build-failure" aria-label="Permalink to &quot;CI Build Failure&quot;">​</a></h2><p><strong>Symptom</strong>: GitHub Actions reports it can&#39;t find DLLs.</p><p><strong>Troubleshooting</strong> (see <a href="./github-actions">GitHub Actions Auto Build</a>):</p><ol><li>Does the private lib repository directory structure match <code>HintPath</code></li><li>Was the <code>LIBS_PAT</code> Secret created and spelled correctly</li><li>Does the PAT have <code>contents: Read</code> permission</li><li>Will the local path <code>Condition</code> be overridden in CI</li></ol><h2 id="game-crash" tabindex="-1">Game Crash <a class="header-anchor" href="#game-crash" aria-label="Permalink to &quot;Game Crash&quot;">​</a></h2><p><strong>Symptom</strong>: The game crashes immediately after enabling the Mod.</p><p><strong>Troubleshooting</strong>:</p><ol><li>Check the last exception stack trace in <code>Player.log</code></li><li>Disable all Mods and enable them one by one to bisect</li><li>If it points to your patch, use a <code>Finalizer</code> to catch exceptions and avoid crashing</li><li>Confirm you haven&#39;t included game binaries in the build output (this causes load conflicts)</li></ol><h2 id="what-you-learned" tabindex="-1">What You Learned <a class="header-anchor" href="#what-you-learned" aria-label="Permalink to &quot;What You Learned&quot;">​</a></h2><ul><li>First-line troubleshooting approach for common problems</li><li>Which detailed chapter each issue maps to</li></ul><h2 id="series-complete-🎉" tabindex="-1">Series Complete 🎉 <a class="header-anchor" href="#series-complete-🎉" aria-label="Permalink to &quot;Series Complete 🎉&quot;">​</a></h2><p>You&#39;ve completed the full ADOFAI Mod development workflow. Next, you can:</p><ul><li>Explore the <a href="./../../libs/">Library Docs</a> to process level files with code</li><li>Try the <a href="./../../mods/online-tools/">Online Tools</a>, or contribute your Mod tutorials to the <a href="./../../mods/">User Guide</a></li></ul>',34)])])}const g=o(l,[["render",i]]);export{p as __pageData,g as default};
